const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const crypto = require('crypto');

// Current reference time based on existing data: 2026-09-02 (order date context)
// creation_timestamp pattern: 1788228000 = 2026-09-01T10:00:00 UTC
// Let's use 2026-09-02T10:00:00 as 'now' and add 7 days for the reminder

const now = new Date('2026-09-02T10:00:00Z');
const oneWeek = new Date('2026-09-09T10:00:00Z');

const creationTs = Math.floor(now.getTime() / 1000);
const reminderTs = Math.floor(oneWeek.getTime() / 1000);
const reminderId = crypto.randomUUID();

console.log('Reminder ID:', reminderId);
console.log('Creation timestamp:', creationTs, '(' + now.toISOString() + ')');
console.log('Reminder timestamp:', reminderTs, '(' + oneWeek.toISOString() + ')');

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, ?)
\`).run(
  reminderId,
  'Follow up on warranty claim WR-NEW005 for Aurora Smart Desk Lamp Pro (Order ORD-E0E671).',
  creationTs,
  reminderTs,
  now.toISOString().replace('.000Z', '')
);

// Verify
const reminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('\nCREATED REMINDER:', JSON.stringify(reminder, null, 2));
"
